INSERT INTO Products (Name, Description, Price, QuantityAvailable, ImagePath, CategoryId) VALUES
('Original 35mm Film Cell Mad Max: Fury Road Film Cell', 'A genuine 35mm film cell from Mad Max: Fury Road, capturing the high-octane chaos of George Miller’s post-apocalyptic masterpiece. A must-have collectible for action film enthusiasts.', 89.99, 15, '/AbsoluteCinemaImages/MadMax.jpg', 2), 
('Limited Edition Die Hard Film Strip Collectible', 'An authentic film strip from Die Hard, featuring iconic frames of John McClane in action. A nostalgic piece of cinema history perfect for collectors of classic action films.', 79.99, 12, '/AbsoluteCinemaImages/DieHard.jpg', 2),
('Authentic 35mm Film Cell Gladiator Film Cell', 'A real 35mm film cell from Gladiator, showcasing a powerful moment from Ridley Scott’s epic tale of revenge and honor. A striking collectible for fans of historical action cinema.', 99.99, 8, '/AbsoluteCinemaImages/Gladiator.jpg', 2),
('Authentic 35mm Film Cell Inception Film Cell', 'A genuine 35mm film cell from Inception, capturing a visually stunning moment from Christopher Nolan’s mind-bending sci-fi thriller. A unique collectible for fans of complex storytelling and cinematic innovation.', 109.99, 9, '/AbsoluteCinemaImages/Inception.jpg', 3),
('Authentic 70mm IMAX film cell Interstellar IMAX Film Cell', 'A genuine 70mm IMAX film cell from Interstellar, capturing a stunning frame from Christopher Nolan’s epic journey through space and time. A rare collectible celebrating the film’s breathtaking visuals and scientific ambition.', 129.99, 6, '/AbsoluteCinemaImages/Interstellar.jpg', 3);
